#!/usr/bin/env python3
"""Record edits of campaign/STRATEGY.md by lane c19-repair-owed-record-r18-checkpoint-prep. No rule, weight or
allocation is changed. Previous file: before/STRATEGY.md. Every anchor matches once."""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
p = os.path.normpath(os.path.join(HERE, '..', '..', 'campaign', 'STRATEGY.md'))
ME = 'c19-repair-owed-record-r18-checkpoint-prep'
L = open(p, encoding='utf-8').read().split('\n')
assert not any(ME in l for l in L), 'already applied'
def idx(prefix):
    k = [i for i, l in enumerate(L) if l.startswith(prefix)]
    assert len(k) == 1, (prefix, len(k)); return k[0]

# ---- section 3.1 heading
k = idx('### 3.1 Families closed by this rule')
a = '42 to 47: round 16)'
assert L[k].count(a) == 1
L[k] = L[k].replace(a, '42 to 47: round 16; 48 to 53: round 17; 54 to 58: round 18, entered by `' + ME + '` as record items)')

# ---- items 48 to 58, after item 47
